<template><PageContainer title="项目" description="管理 Agent 可以访问的本地工作目录。"><template #extra><el-button type="primary" @click="create"><AppIcon name="Plus" />新建项目</el-button></template><div v-loading="loading" class="project-grid"><article v-for="project in projects" :key="project.id" class="project-card"><div class="project-card__title"><AppIcon name="FolderOpened" /><strong>{{ project.name }}</strong><el-dropdown @command="(command: string) => handleCommand(command, project)"><el-button text aria-label="项目操作"><AppIcon name="MoreFilled" /></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="open">打开</el-dropdown-item><el-dropdown-item command="rename">重命名</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><p>{{ project.directory }}</p><dl><div><dt>会话</dt><dd>{{ project.sessionCount }}</dd></div><div><dt>最近活跃</dt><dd>{{ formatTime(project.lastSessionAt || project.updatedAt) }}</dd></div></dl></article><button class="project-card project-card--new" type="button" @click="create"><AppIcon name="Plus" /><span>选择本地目录创建项目</span></button></div><el-empty v-if="!loading && !projects.length" description="选择一个本地目录，开始第一个 Agent 项目" /></PageContainer></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { getPlatformApi } from '@/platform'; import type { HarnessProject } from '@/config/harness'; import PageContainer from '@/components/PageContainer/index.vue'; import { useRouter } from 'vue-router'; const router = useRouter(); const projects = ref<HarnessProject[]>([]); const loading = ref(false); async function load(){ loading.value=true; try{ projects.value=await getPlatformApi()?.listHarnessProjects()||[] }finally{loading.value=false} } async function create(){ const project=await getPlatformApi()?.createHarnessProject(); if(project){ElMessage.success('项目已创建');await load()} } function formatTime(value:number){return new Intl.RelativeTimeFormat('zh-CN',{numeric:'auto'}).format(Math.round((value-Date.now())/86400000),'day')} async function handleCommand(command:string, project:HarnessProject){if(command==='open'){const session=await getPlatformApi()?.createHarnessSession(project.id);if(session) await router.push(`/workspace/chat/${session.id}`)} if(command==='rename'){const {value}=await ElMessageBox.prompt('输入新的项目名称','重命名项目',{inputValue:project.name});await getPlatformApi()?.renameHarnessProject(project.id,value);await load()} if(command==='delete'){await ElMessageBox.confirm('仅移除项目注册；源文件会保留。','删除项目',{confirmButtonText:'移除注册',cancelButtonText:'取消',type:'warning'});await getPlatformApi()?.deleteHarnessProject(project.id,false);await load()} } onMounted(load);</script>
<style scoped lang="scss">.project-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:$spacing-md}.project-card{min-height:155px;padding:$spacing-lg;border:1px solid var(--cp-border-light);border-radius:$radius-md;background:var(--cp-bg-elevated);text-align:left}.project-card__title{display:flex;align-items:center;gap:8px}.project-card__title strong{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.project-card p{min-height:36px;margin:14px 0;color:var(--cp-text-tertiary);font-size:$font-xs;line-height:1.5;overflow-wrap:anywhere}.project-card dl{display:flex;gap:28px;margin:0}.project-card dt{color:var(--cp-text-tertiary);font-size:11px}.project-card dd{margin:4px 0 0;font-size:$font-sm}.project-card--new{display:flex;align-items:center;justify-content:center;gap:9px;border-style:dashed;color:var(--cp-text-secondary);cursor:pointer}.project-card--new:hover{color:var(--cp-primary);border-color:var(--cp-primary)}</style>
